@Component
@RequiredArgsConstructor
class AperturaBaseSemanal {

    private final BaseSemanalDataSource base;
    private final P111Properties props;

    /** 000700-ABRE-BASE. Reintenta mientras la base esté en uso exclusivo (DMERRORTYPE 39). */
    void abre(int estatusBaseSemanal) throws InterruptedException {
        if (estatusBaseSemanal != 0) {
            throw new ProcesoAbortadoException("ESTADO INVALIDO DE LA BASE DE MOVTOS");
        }
        for (int intento = 1; ; intento++) {
            try {
                base.abreParaActualizar();
                return;
            } catch (BaseEnUsoExclusivoException e) {
                if (intento % props.apertura().avisoCada() == 0) {
                    log.warn("ERROR EN BASE BD10 : ARCHIVO DE CONTROL EN USO EN FORMA EXCLUSIVA");
                }
                Thread.sleep(props.apertura().espera().toMillis());
            } catch (DataAccessException e) {
                throw new ProcesoAbortadoException("ERROR AL ABRIR LA BASE SEMANAL", e);
            }
        }
    }
}

@Component
@StepScope
@RequiredArgsConstructor
class DepuraTotalesTasklet implements Tasklet {

    private final TotalPorClaveRepository b50;
    @Value("#{jobExecutionContext['fechaProceso']}") private LocalDate fechaProceso;

    /** 000800-DELETE-B50SXTOTXCVE + 000810-NEXT-DELETE. */
    @Override
    @Transactional                      // un solo commit; el COBOL hace una transacción NO-AUDIT por registro
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        int borrados = b50.deleteByFechaLessThanEqual(fechaProceso);   // AT B50-MOV-FEC NOT > WKS-FEC-PRO
        c.incrementWriteCount(borrados);
        return RepeatStatus.FINISHED;
    }
}

interface TotalPorClaveRepository extends JpaRepository<TotalPorClave, TotalPorClave.Llave> {
    @Modifying
    @Query("delete from TotalPorClave t where t.llave.fecha <= :fecha")
    int deleteByFechaLessThanEqual(@Param("fecha") LocalDate fecha);
}

/** Lector del archivo de movimientos con el centinela de función 99. */
@Component
@StepScope
@RequiredArgsConstructor
class MovimientoReader implements ItemReader<Movimiento> {

    private final FlatFileItemReader<Movimiento> archivo;     // L01-DATOS, el header ya se consumió
    private final FiltroTeleton teleton;
    private boolean fin;

    @Override
    public Movimiento read() throws Exception {
        while (!fin) {
            Movimiento m = archivo.read();
            if (m == null || m.funcion() == 99) {             // AT END o trailer lógico
                fin = true;
                return null;
            }
            if (!teleton.excluye(m)) {
                return m;
            }
        }
        return null;
    }
}

@Component
@StepScope
@RequiredArgsConstructor
class ConceptosProcessor implements ItemProcessor<Movimiento, List<RegistroTotal>> {

    @Value("#{jobParameters['sistema']}") private Integer sistema;
    private final P111Properties props;   // p111.s500.claves-reclasifica: [3009, 3036]
                                          // p111.sistemas-sin-banco-default: [403, 404]

    /** 001000-ARMA-ARCHIVO. */
    @Override
    public List<RegistroTotal> process(Movimiento m) {
        int producto = (sistema == 87) ? 87 : m.producto();
        int tipoProceso = m.tipoProceso();
        if (sistema == 500) {
            boolean reclasifica = (tipoProceso >= 15 && tipoProceso <= 17)
                    && props.s500().clavesReclasifica().contains(m.claveTransaccion(1));
            tipoProceso = (tipoProceso < 15 || reclasifica) ? 1 : 11;
        }
        if (m.funcion() != 1 || m.estatus() != 1) {
            return null;                                  // no se escribe nada
        }
        Bancos bancos = switch (sistema) {
            case 500 -> new Bancos(m.bancoOrigen(), m.bancoDestino());
            case 403, 404 -> Bancos.SIN_ASIGNAR;           // COBOL: NEXT SENTENCE, ver riesgo
            default -> new Bancos(2, 2);
        };
        var base = new LlaveTotal(m.fechaContable(), tipoProceso, producto,
                                  m.instrumento(), m.moneda(), bancos, 0);
        return conceptos(base, m);                         // 001100-ARMA-REGISTRO x 5
    }
}

@Component
@RequiredArgsConstructor
class FiltroTeleton {
    private final P111Properties props;   // p111.s500.tipos-teleton: [40, 41, 42, 43]
    @Value("#{jobParameters['sistema']}") private Integer sistema;

    /** <<INICIO-IBM>> MGGR EXCLUSION DE MOVIMIENTOS TELETON. */
    boolean excluye(Movimiento m) {
        return sistema == 500 && props.s500().tiposTeleton().contains(m.tipoProceso());
    }
}

/** 001100-ARMA-REGISTRO VARYING W77-IND FROM 1 BY 1 UNTIL W77-IND > 5. */
static List<RegistroTotal> conceptos(LlaveTotal base, Movimiento m) {
    return IntStream.rangeClosed(1, 5)
            .mapToObj(m::concepto)
            .filter(c -> c.claveTransaccion() > 0)
            .map(c -> new RegistroTotal(base.con(c.claveTransaccion(), c.esquemaContable()),
                                        c.importe()))          // 9(16)V99 -> escala 2
            .toList();
}

/** WKS-RS-LLAVE: orden del SORT y llave natural de B50. */
public record LlaveTotal(LocalDate fecha,          // 9(08) CCAAMMDD = FECCONT del movimiento
                         int tipoProceso,          // 9(02)
                         int producto,             // 9(04)
                         int instrumento,          // 9(02)
                         int moneda,               // 9(04)
                         Bancos bancos,            // 9(05) origen + 9(05) destino
                         int tipoMovimiento,       // 9(02), siempre 0
                         int claveTransaccion,     // 9(06)
                         int esquemaContable)      // 9(04)
        implements Comparable<LlaveTotal> {

    private static final Comparator<LlaveTotal> ORDEN = Comparator
            .comparing(LlaveTotal::fecha).thenComparingInt(LlaveTotal::tipoProceso)
            .thenComparingInt(LlaveTotal::producto).thenComparingInt(LlaveTotal::instrumento)
            .thenComparingInt(LlaveTotal::moneda).thenComparing(LlaveTotal::bancos)
            .thenComparingInt(LlaveTotal::tipoMovimiento)
            .thenComparingInt(LlaveTotal::claveTransaccion).thenComparingInt(LlaveTotal::esquemaContable);

    @Override public int compareTo(LlaveTotal o) { return ORDEN.compare(this, o); }
}

public record RegistroTotal(LlaveTotal llave, BigDecimal importe) {}   // WKS-RS-IMPORTE 9(16)V99

/** SORT + 002100-ARMA-BDTOTXCVE: agrupa sin necesidad de archivo intermedio. */
@Component
@StepScope
class AcumuladorPorClave implements ItemWriter<List<RegistroTotal>> {

    private final SortedMap<LlaveTotal, Total> totales = new TreeMap<>();

    @Override
    public void write(Chunk<? extends List<RegistroTotal>> chunk) {
        chunk.getItems().stream().flatMap(List::stream).forEach(r ->
                totales.merge(r.llave(), new Total(1, r.importe()), Total::suma));
    }

    SortedMap<LlaveTotal, Total> resultado() { return totales; }
}

record Total(long numMovimientos, BigDecimal importe) {
    private static final BigDecimal TOPE = new BigDecimal("9999999999999999.99");   // W77-IMPMOV 9(16)V99
    Total suma(Total o) {
        BigDecimal imp = importe.add(o.importe);                  // ADD sin ROUNDED: exacto en escala 2
        if (imp.compareTo(TOPE) > 0 || numMovimientos + o.numMovimientos > 99_999_999L) {
            throw new DesbordamientoAcumuladorException(imp);     // COBOL truncaría en silencio
        }
        return new Total(numMovimientos + o.numMovimientos, imp);
    }
}

@Component
@RequiredArgsConstructor
class TotalesPorClaveWriter {

    private final TotalPorClaveRepository b50;

    /** 002200-ACT-BD: LOCK por llave completa; si no existe CREATE; en ambos casos STORE. */
    @Transactional
    public void graba(SortedMap<LlaveTotal, Total> totales) {
        totales.forEach((llave, total) -> {
            TotalPorClave t = b50.findByLlaveForUpdate(llave)      // LOCK B50SXTOTXCVE AT ...
                    .orElseGet(() -> TotalPorClave.nuevo(llave));  // CREATE S151B50TOTXCVE
            t.setNumMovimientos(total.numMovimientos());           // MOVE, no ADD: reemplaza
            t.setImporte(total.importe());
            b50.save(t);                                           // STORE
        });
    }
}
